export const WEAPON_COMPENDIUM=Object.freeze(ROWS.map(v=>Object.freeze(v)));
export const WEAPON_COMPENDIUM_COUNT=ROWS.length;
export function weaponCompendium({query='',skill=null,restricted=null,limit=1000}={}){const q=String(query??'').trim().toLocaleLowerCase('pt-BR');const s=String(skill??'').trim();const max=Math.max(1,Math.min(2000,Number(limit)||1000));return ROWS.filter(v=>(!q||[v.name,v.qualitiesRaw,v.notes].some(x=>String(x??'').toLocaleLowerCase('pt-BR').includes(q)))&&(!s||v.skill===s)&& (restricted===null||restricted===undefined||v.restricted===Boolean(restricted))).slice(0,max).map(v=>structuredClone(v));}
export function weaponCompendiumEntry(id){const v=ROWS.find(x=>x.id===String(id??''));return v?structuredClone(v):null;}
